import{_ as t,o,c as a,a2 as n}from"./chunks/framework.DGk0zlJw.js";const p=JSON.parse('{"title":"Beacon privacy policy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md"}'),i={name:"privacy-policy.md"};function r(s,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="beacon-privacy-policy" tabindex="-1">Beacon privacy policy <a class="header-anchor" href="#beacon-privacy-policy" aria-label="Permalink to &quot;Beacon privacy policy&quot;">​</a></h1><p>Last updated: 2026-10-12 · Applies to: v0.1.x (including daily builds)</p><h2 id="in-one-sentence" tabindex="-1">In one sentence <a class="header-anchor" href="#in-one-sentence" aria-label="Permalink to &quot;In one sentence&quot;">​</a></h2><p><strong>Beacon does not collect data and uploads nothing to the developer&#39;s servers.</strong> All data lives only on your own computer; network requests go only to the API endpoints you configure yourself and to this project&#39;s official repository update-check endpoint.</p><h2 id="what-data-is-collected" tabindex="-1">What data is collected <a class="header-anchor" href="#what-data-is-collected" aria-label="Permalink to &quot;What data is collected&quot;">​</a></h2><p>Beacon stores three kinds of data <strong>locally on your computer</strong>, all of it entered by you or produced by running on this machine:</p><table tabindex="0"><thead><tr><th>Category</th><th>Contents</th><th>Source</th></tr></thead><tbody><tr><td>Credentials</td><td>GitHub PAT, API keys of AI platforms (Zhipu / Kimi / DeepSeek / Volcengine Ark / Alibaba Qwen / Xiaomi MiMo / Claude / Codex / Copilot / OpenCode etc., depending on the connections you configure)</td><td>Entered by you in the settings UI</td></tr><tr><td>Configuration</td><td>Connection settings, refresh intervals, theme, widgets and pinned layout, actions (including optional webhooks)</td><td>Adjusted by you in the settings UI</td></tr><tr><td>Local machine readings</td><td>CPU / memory / disk / network speed / IP address etc., used only for local display</td><td>Sampled on this machine</td></tr></tbody></table><p>Beacon has <strong>no</strong> account system, <strong>no</strong> telemetry or analytics, and <strong>does not</strong> report any data to the developer or to any third party.</p><h2 id="where-the-data-lives" tabindex="-1">Where the data lives <a class="header-anchor" href="#where-the-data-lives" aria-label="Permalink to &quot;Where the data lives&quot;">​</a></h2><p>Everything is in the local user directory <code>%AppData%\\Beacon\\</code> (that is, <code>%APPDATA%\\Beacon</code>, a normal user profile, no administrator needed):</p><table tabindex="0"><thead><tr><th>File / directory</th><th>Contents</th><th>How it is protected</th></tr></thead><tbody><tr><td><code>secrets.bin</code></td><td>All credentials</td><td><strong>Encrypted with DPAPI (CurrentUser)</strong> — only the same Windows account can decrypt it; the file itself contains no plaintext</td></tr><tr><td><code>connections.json</code></td><td>Connection settings</td><td><strong>Contains no plaintext credentials</strong>: it stores only credentialRef references; the secrets themselves are in <code>secrets.bin</code></td></tr><tr><td><code>config.json</code> / <code>widgets.json</code> / <code>pins.json</code> / <code>actions.json</code></td><td>Global settings / widgets / pins / actions</td><td>Plaintext JSON, no credentials</td></tr><tr><td><code>cache\\</code></td><td>The most recent cached state of each widget</td><td>Plaintext JSON</td></tr><tr><td><code>notifications.json</code></td><td>Notification history and read state</td><td>Plaintext JSON</td></tr><tr><td><code>logs\\</code></td><td>Runtime logs</td><td>Plain text (for troubleshooting)</td></tr></tbody></table><p>A configuration export/import package <strong>never contains credentials</strong> — the exported file holds only credentialRef references, and you must re-enter the secrets on the new machine.</p><h2 id="how-data-leaves-this-machine" tabindex="-1">How data leaves this machine <a class="header-anchor" href="#how-data-leaves-this-machine" aria-label="Permalink to &quot;How data leaves this machine&quot;">​</a></h2><p>Beacon makes only three kinds of outgoing network requests, all expected and all switchable:</p><ol><li><strong>Update check</strong> (on by default, no switch yet): 20 seconds after startup it sends one GET to this project&#39;s public repository endpoint <code>api.github.com/repos/cuihairu/beacon/releases/latest</code> (once per process lifetime; the manual &quot;Check for updates&quot; button forces a re-check) — the request carries only a User-Agent (<code>Beacon-Update-Check</code>) and your IP (which any network request carries), <strong>and no personal data whatsoever</strong>.</li><li><strong>Connection queries</strong>: sent only to the API endpoints <strong>you configured yourself</strong> (the GitHub API, the console / usage endpoints of the AI platforms), authenticated with the key you entered. Beacon contacts exactly the endpoints you configured; delete the connection and it stops.</li><li><strong>Actions</strong>: only when you have configured HTTP / webhook actions does Beacon send requests to the URL you specified (webhooks carry an HMAC-SHA256 signature header; the secret likewise lives only in DPAPI).</li></ol><p>Apart from these three, Beacon opens no other network connection.</p><h2 id="what-the-data-is-used-for" tabindex="-1">What the data is used for <a class="header-anchor" href="#what-the-data-is-used-for" aria-label="Permalink to &quot;What the data is used for&quot;">​</a></h2><p>Local data is used only to: display state on your screen (the capsule, floating widgets, the quick panel), execute the local actions you configured, and maintain settings and notification history. Credentials are used only to authenticate queries against the corresponding platforms and for nothing else.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and deletion&quot;">​</a></h2><ul><li>Data lives as long as the install directory does; uninstall through the system&#39;s &quot;Add or Remove Programs&quot; (or just delete the portable directory), then delete <code>%AppData%\\Beacon\\</code> to <strong>completely remove all local data</strong>, including the encrypted credentials.</li><li>Beacon has no cloud copy — deleted is deleted.</li><li>The import/export feature in the settings UI moves configuration only (no credentials) and does not affect this item.</li></ul><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions about this policy or data handling:</p><ul><li>GitHub: <a href="https://github.com/cuihairu" target="_blank" rel="noreferrer">github.com/cuihairu</a> (filing an issue on <a href="https://github.com/cuihairu/beacon" target="_blank" rel="noreferrer">cuihairu/beacon</a> works)</li></ul>',23)])])}const y=t(i,[["render",r]]);export{p as __pageData,y as default};
